def compactar_rle(texto):
    if not texto: return ""
    res = []
    atual = texto[0]
    count = 1
    for char in texto[1:]:
        if char == atual:
            count += 1
        else:
            res.append(f"{atual}{count}")
            atual = char
            count = 1
    res.append(f"{atual}{count}")
    return "".join(res)

